define(['jquery', 'Magento_Ui/js/modal/modal', 'mage/cookies'], function($, modal, cookies) {
    return function(config) {
        var cookiedomain = config.cookiedomain;
        if (cookiedomain == "") {
            cookiedomain = '.' + window.location.host
        }
        var options_model = {
            type: 'popup',
            responsive: true,
            innerScroll: true,
            modalClass: 'zero-qty-model',
            title: "Warning!",
            buttons: [{
                text: $.mage.__('OK'),
                class: '',
                click: function() {
                    this.closeModal();
                }
            }]
        };
        $(document).ajaxSuccess(function(event, xhr, settings) {
            var urlString = settings.url;
            if (settings.url.indexOf('checkout/sidebar/removeItem') !== -1 || settings.url.indexOf('checkout/sidebar/updateItemQty') !== -1) {
                $.ajax({
                    url: location.origin + '/customizecheckout/index/checkminicartquote',
                    method: "POST",
                    dataType: "json"
                }).done(function(response) {
                    if (response.success) {
                        if (response.current_apply == 'vouchergram') {
                            setTimeout(() => {
                                var popup = modal(options_model, $('#check-zero-qty-model'));
                                $("#check-zero-qty-model").modal(options_model).modal("openModal");
                            }, 800);
                            var mobile = response.mobile;
                            var check_v = response.current_apply;
                            if (check_v != '' && mobile != '') {
                                var apiurl = window.location.origin + "/vouchergram/index/reversevoucher";
                                $.ajax({
                                    url: apiurl,
                                    method: 'POST',
                                    type: 'POST',
                                    data: {
                                        mobile: mobile,
                                        check_vg: check_v
                                    },
                                    success: function(result) {}
                                });
                                var apiurls = window.location.origin + "/vouchergram/index/revertgiftcard";
                                $.ajax({
                                    url: apiurls,
                                    method: 'POST',
                                    type: 'POST',
                                    data: {
                                        gift_type: check_v
                                    },
                                    success: function(results) {
                                        reverseVcFunction(response.mobile, response.current_apply);
                                        $.cookie("current_apply", null, {
                                            path: '/',
                                            expires: -1,
                                            domain: cookiedomain
                                        });
                                        setTimeout(function() {
                                            window.location.reload();
                                        }, 2500);
                                    }
                                });
                            }
                        }
                        if (response.current_apply == 'quicksilver') {
                            var popup = modal(options_model, $('#check-zero-qty-model'));
                            $("#check-zero-qty-model").modal(options_model).modal("openModal");
                            var apiurl = window.location.origin + "/promoapi/user/cancelqc/";
                            jQuery.ajax({
                                url: apiurl,
                                method: 'POST',
                                dataType: 'json',
                                type: 'POST',
                                data: {},
                                success: function(result) {}
                            });
                            var apiurls = window.location.origin + "/vouchergram/index/revertgiftcard";
                            jQuery.ajax({
                                url: apiurls,
                                method: 'POST',
                                type: 'POST',
                                data: {
                                    gift_type: response.current_apply
                                },
                                success: function(results) {
                                    $.cookie("current_apply", null, {
                                        path: '/',
                                        expires: -1,
                                        domain: cookiedomain
                                    });
                                    $.cookie("redamt", null, {
                                        path: '/',
                                        expires: -1,
                                        domain: cookiedomain
                                    });
                                    reverseVcFunction(response.mobile, response.current_apply);
                                    setTimeout(function() {
                                        window.location.reload();
                                    }, 2000);
                                }
                            });
                        }
                    }
                });
            }
        });

        function reverseVcFunction(mobile, check_v) {
            if (check_v != '' && mobile != '') {
                var baseUrl = baseUrl;
                var apiurl = location.origin + "/vouchergram/index/revertgiftcard";
                $.ajax({
                    url: apiurl,
                    method: 'POST',
                    type: 'POST',
                    data: {
                        mobile: mobile,
                        check_vg: check_v,
                        isCartRm: "yes"
                    },
                    success: function(result) {}
                });
            }
            if (check_v == 'quicksilver' && mobile != '') {
                var url = location.origin + "/promoapi/user/cancelredeem/";
                jQuery.ajax({
                    dataType: 'json',
                    url: url,
                    type: "POST",
                    data: {},
                    success: function(response) {}
                });
            }
            if (check_v != '' && check_v == "vouchergram" && mobile != '') {
                var baseUrl = baseUrl;
                var apiurl = location.origin + "/vouchergram/index/reversevoucher";
                $.ajax({
                    url: apiurl,
                    method: 'POST',
                    type: 'POST',
                    data: {
                        mobile: mobile,
                        check_vg: check_v
                    },
                    success: function(result) {}
                });
            }
        }
    }
});